"""Private Braun 2001 main-article reader; no Site or publication side effects."""
from pathlib import Path
from collections import Counter
import json,hashlib,re
B=Path(__file__).resolve().parents[1];O=Path(__file__).resolve().parent
SID='braun2001';PAGE='braun2001';P='braun-2001-'
read=lambda p:json.loads(p.read_text(encoding='utf8'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
source=read(B/'source-manifest.json');manifest=read(B/'reader-assets/crop-manifest.json')
sections=[{'id':k,'title':v,'items':[]} for k,v in [('precursors','Precursors'),('protocol','Synthesis protocol'),('structures','Final structures'),('properties','Properties'),('intuition','Chemical intuition'),('sources','Sources and limitations')]];items={}
SCOPE={'source_cohort':'Source system or stage label only. Repeated initial spectra do not prove a common physical batch across systems.','method_context':'Reported preparation or acquisition context; not an independently measured specimen property.','model_context':'Source interpretation or schematic, not a measured atomic structure or independently validated theory.','cited_context':'Context cited in this article; external cited documents were not independently inspected in this review.','source_metadata':'Bibliographic identity, coverage or administrative provenance, not a synthesis quantity.','author_outlook':'Proposed future work, not an executed synthesis or current measured outcome.','curator_interpretation':'Explicit source conflict or curation limit, kept separate from measured evidence.'}
ROUTES=['system-i','system-ii','system-iii']
def ev(page,loc):return {'source_id':SID,'document_role':'main','pdf_page':page,'printed_page':5547+page,'locator':f'Main PDF p. {page}, printed p. {5547+page}, {loc}'}
def item(sec,key,title,text,page,loc,records=(),scope='source_cohort',kind='reported_source_fact',notes=()):
 assert key not in items,key
 e=ev(page,loc);d={'id':key,'title':title,'text':text,'claim_type':kind,'sample_scope':{'formulations':[],'physical_batch_id':None,'scope_kind':scope,'state':title,'link_limit':SCOPE[scope]},'evidence':[e],'source_locators':[e['locator']],'canonical_links':[{'record_id':P+k,'json_pointer':'','relation':SCOPE[scope]} for k in records],'notes':list(notes),'facts':[],'training_eligible':False}
 items[key]=d;next(s for s in sections if s['id']==sec)['items'].append(d);return d
def more(key,page,loc):
 e=ev(page,loc);items[key]['evidence'].append(e);items[key]['source_locators'].append(e['locator'])
def rows(sec,data):
 for x in data:item(sec,*x)

rows('precursors',[
('cadmium-stock','Cadmium ion solution','Step A uses 100 mL aqueous Cd²⁺ solution at 2 × 10⁻⁴ M. The cadmium salt, counterion, supplier, purity and solution preparation are not identified. Additional Cd²⁺ is required for a CdS-growth step that does not immediately follow Hg²⁺ exchange, but its amount and stock concentration are not reported.',1,'Sample Preparation, step A',ROUTES,'method_context'),
('mercury-stock','Mercury ion solution','Step B adds 12 mL aqueous Hg²⁺ solution at 10⁻³ M and pH 7.0 to exchange the outermost CdS layer. The Hg salt, counterion, supplier, purity and stock preparation are unspecified. The displayed ion must not be replaced by an assumed HgCl₂ or another named salt.',2,'Sample Preparation, step B',ROUTES,'method_context'),
('h2s-gas','Hydrogen sulfide gas','Step A injects 0.6 mL H₂S gas. Gas temperature, pressure and purity are not supplied, so this volume is not converted into an exact amount of substance. This core-nucleation gas addition is distinct from the later aqueous H₂S feed.',1,'Sample Preparation, step A',ROUTES,'method_context'),
('h2s-water','Aqueous hydrogen sulfide feed','Step C introduces H₂S/water solution dropwise over 25 min at pH 7.0. Feed concentration and volume are not reported. A gas dose from step A must not be assigned to this aqueous growth feed.',2,'Sample Preparation, step C',ROUTES,'method_context'),
('stabilizer','Hexametaphosphate stabilizer','Hexametaphosphate stabilizes the starting aqueous CdS colloid. Its amount, concentration, counterion, supplier, purity and exact polymer or ring distribution are not specified. The source does not establish a unique sodium-salt formulation or a discrete measured ligand geometry.',1,'Sample Preparation, step A',ROUTES,'method_context'),
('water-argon','Water and argon','Water is the reaction solvent and photoluminescence reference. Argon provides the step-A atmosphere and removes excess H₂S after core formation and CdS growth. Argon flow, purity, line pressure and later Hg-exchange atmosphere are not quantified; no synthesis temperature follows automatically from the room-temperature optical measurements.',1,'Sample Preparation and Experimental Section',ROUTES,'method_context'),
('stocks-limits','Stock composition and pH adjustments','The paper gives aqueous ion concentrations and selected pH values but no acid/base identity or titration procedure. It cites references 2 and 13 for preparation details beyond this summary. Missing stock and pH-adjustment details remain unknown rather than copied from an uninspected external recipe.',2,'Sample Preparation, steps B–C',ROUTES,'curator_interpretation','reviewed_source_limitation'),
])
more('cadmium-stock',2,'Step C conditional Cd²⁺ addition');more('water-argon',2,'Post-growth argon purge')

rows('protocol',[
('sequence-framework','Three reusable preparation steps','The reported synthesis comprises A: CdS core growth; B: exchange of the outermost CdS monolayer for HgS; and C: growth of a CdS monolayer. The order determines whether the final particle contains one HgS monolayer, one contiguous HgS double layer or two separated HgS monolayers. References 2 and 13 are dependencies for details not reproduced here.',1,'Sample Preparation introduction',ROUTES,'method_context'),
('step-a-charge','Step A: nucleate CdS cores','In a 250 mL flask under argon, stir 100 mL 2 × 10⁻⁴ M aqueous Cd²⁺ with hexametaphosphate at initial pH 7.9 and inject 0.6 mL H₂S gas. The source does not state stirring speed, injection duration, stabilizer dose or a numerical synthesis temperature.',1,'Sample Preparation, step A',ROUTES,'method_context'),
('step-a-grow','Step A: pH evolution and growth','The authors describe rapid initial nucleation followed by slower growth as acidification proceeds. The mixture reaches an acidic range after about 30 s and a final pH of 4.6. This is not a reported 30 s total growth time. The preparation paragraph states a final size of 3.5 nm, while the subsequent system description and Figure 1 use a 3.2 nm core.',1,'Step A pH evolution',ROUTES,'method_context'),
('step-a-purge','Step A: remove excess hydrogen sulfide','After core growth, purge the colloidal solution with argon for 20 min to remove excess H₂S. The source does not state gas flow, pressure or a quantitative residual-H₂S endpoint. No isolation or drying is inserted between this step and the aqueous shell operations.',2,'Step A continuation',ROUTES,'method_context'),
('step-b','Step B: surface cation exchange','Add 12 mL 10⁻³ M aqueous Hg²⁺ at pH 7.0. The source describes replacement of one outer CdS monolayer by one HgS monolayer, with the displaced Cd²⁺ remaining in solution. An exchange dwell time or a direct conversion assay is not supplied.',2,'Sample Preparation, step B',ROUTES,'method_context'),
('step-c-cadmium','Step C: establish the available Cd²⁺ supply','When C immediately follows B, the authors state that displaced Cd²⁺ is sufficient for one CdS monolayer. Otherwise, inject the required Cd²⁺ through a septum before growing CdS. This conditional branch matters for the repeated C steps in system III. The supplemental Cd²⁺ amount and concentration are not quantified.',2,'Sample Preparation, step C',ROUTES,'method_context'),
('step-c-feed','Step C: grow CdS and purge','At pH 7.0, add H₂S/water solution slowly and dropwise over 25 min to grow one CdS monolayer. Subsequently purge with argon for at least 20 min. Feed amount and concentration, addition hardware, mixing rate and temperature are not reported; the purge duration retains its lower bound.',2,'Sample Preparation, step C',ROUTES,'method_context'),
('system-i-sequence','System I: A–B–C','Grow the CdS core, exchange its outermost monolayer for HgS and add one CdS capping layer. The resulting source architecture is CdS/(HgS)₁/(CdS)₁: one HgS quantum well between the CdS core and clad.',2,'Single-Layer Well QDQW',['system-i']),
('system-ii-sequence','System II: A–B–C–B–C','Prepare system I, exchange its newly grown CdS cap for a second contiguous HgS monolayer, then add the final CdS cap. The resulting source architecture is CdS/(HgS)₂/(CdS)₁. This is one thicker well, not two separated wells.',2,'Double-Layer Well QDQW',['system-ii']),
('system-iii-sequence','System III: A–B–C–C–C–B–C','After the first A–B–C sequence, grow two further CdS monolayers, leaving three CdS layers outside the first HgS well. Exchange only the outermost of those three for HgS and then cap with CdS. The remaining two CdS layers separate the two HgS wells: CdS/(HgS)₁/(CdS)₂/(HgS)₁/(CdS)₁.',2,'Two-Wells QDQW',['system-iii']),
('absorption-method','Steady-state absorption acquisition','Absorption spectra are reported after selected synthesis stages at room temperature. Figure 2 provides optical density versus energy with a wavelength scale. A separate spectrophotometer model, spectral bandwidth, concentration normalization, sample path length or raw numerical spectrum is not supplied for this steady-state experiment.',2,'Results: Absorption Spectra',['absorption-acquisition'],'method_context'),
('pl-method','Photoluminescence acquisition','Excite at 440 nm using an optical parametric oscillator pumped by the third harmonic of a Q-switched Nd:YAG laser. The Nd:YAG pump is reported to provide 5 ns pulses at 10 Hz; an independent OPO output pulse-width measurement is not supplied. Collect emission in a 90° geometry using a cutoff filter, monochromator and CCD. Subtract a water-reference spectrum to remove Raman bands and background. The room-temperature condition belongs to the measurement statement.',1,'Experimental Section: photoluminescence',['photoluminescence-acquisition'],'method_context'),
('ta-excitation','Transient absorption: pump and probe','Pump the colloid at 400 nm with 100 fs FWHM pulses and 100 µJ pulse energy. Generate a 450–1,050 nm white-light continuum by focusing part of the 800 nm fundamental laser output into sapphire. Overlap pump and probe in the sample and measure pump-induced absorption changes versus delay.',1,'Experimental Section: fs transient absorption',['transient-absorption-acquisition'],'method_context'),
('ta-delay','Transient absorption: delay and sample handling','Vary delay with an optical delay line whose resolution is 3 µm, reported as 21 fs. Rotate the colloidal solution in a 2 mm thick glass cell to reduce photodegeneration. Experiments are at room temperature. Delay-line resolution is not the fitted lifetime, pulse width or total instrument response.',1,'Experimental Section: fs transient absorption',['transient-absorption-acquisition'],'method_context'),
])
more('step-a-grow',2,'Step A continuation and system dimensions');more('absorption-method',3,'Figure 2');more('sequence-framework',2,'Systems I–III orders')

rows('structures',[
('system-i-structure','System I: one monolayer quantum well','The source assigns a 3.2 nm CdS core, a 0.4 nm HgS well and a 0.4 nm CdS cap. These dimensions describe the author’s layer model for system I. Figure 1 is a schematic, not a current microscopic image or crystallographic refinement.',2,'Figure 1 and system dimensions',['system-i']),
('system-ii-structure','System II: one double-layer quantum well','The source assigns a 3.2 nm CdS core, one contiguous 0.8 nm HgS double layer and a 0.4 nm CdS cap. Two HgS monolayers without an intervening CdS barrier constitute a single wider well.',2,'Figure 1 and system dimensions',['system-ii']),
('system-iii-structure','System III: two separated quantum wells','The source assigns a 3.2 nm CdS core, 0.4 nm first HgS well, 0.8 nm CdS barrier, 0.4 nm second HgS well and 0.4 nm final CdS cap. The two wells are spatially separated in the architecture, but the optical shifts lead the authors to infer electronic interaction between them.',2,'Figure 1 and system dimensions',['system-iii']),
('figure1-scope','Figure 1: architecture and wavefunction schematic','The original figure uses green for CdS and red for HgS, with schematic radial potential profiles and carrier wavefunctions. The radius axis has 0–3 nm ticks and no calibrated energy or wavefunction-amplitude scale. The caption cites Figure 4 of reference 18 for the wavefunction sketches. This is not new measured charge-density data or an atomistic model of the present samples.',2,'Figure 1 caption',ROUTES+['chemical-interpretation'],'model_context','author_schematic'),
('morphology-scope','Morphology and crystal-structure evidence','The introduction and Figure 1 caption cite earlier work describing small CdS crystallites as tetrahedral with {111} facets. No new TEM, HRTEM, SAED, XRD, lattice constants, crystal phase assignment, unit-cell coordinates or measured CIF is provided in these four pages. The circular schematic is not a claim that the particles are spherical.',1,'Introduction and cited morphology',['literature-context'],'cited_context'),
('structural-inference','Optical support for separated wells','The absorption and emission comparisons support the authors’ assignment of a second separated HgS well in system III rather than thickening the first well as in system II. This is an optical/chemical architecture argument. It does not directly resolve each interface, establish atomically uniform coverage or quantify a fraction of correctly layered particles.',3,'Figure 3 caption and emission discussion',['chemical-interpretation'],'model_context','author_interpretation'),
])
more('morphology-scope',2,'Figure 1 caption');more('figure1-scope',4,'Discussion: system III theory unavailable')

stages={
'i':[('a','CdS core'),('b','CdS/(HgS)₁'),('c','CdS/(HgS)₁/(CdS)₁')],
'ii':[('a','CdS core'),('b','CdS/(HgS)₁'),('c','CdS/(HgS)₁/(CdS)₁'),('d','CdS/(HgS)₂ before recapping'),('e','CdS/(HgS)₂/(CdS)₁')],
'iii':[('a','CdS core'),('b','CdS/(HgS)₁'),('c','CdS/(HgS)₁/(CdS)₁'),('d','CdS/(HgS)₁/(CdS)₃'),('e','CdS/(HgS)₁/(CdS)₂/(HgS)₁'),('f','CdS/(HgS)₁/(CdS)₂/(HgS)₁/(CdS)₁')],
}
for system,labels in stages.items():
 mapping='; '.join(letter+': '+label for letter,label in labels)
 item('properties','absorption-stages-'+system,'System '+system.upper()+': absorption-stage assignments','Figure 2 panel '+system.upper()+' associates its spectra as follows: '+mapping+'. The first three spectra are described as identical across the three panels, but the paper does not establish a unique shared physical batch identifier. No additional spectrum is invented for intermediate C repetitions not separately plotted.',3,'Figure 2, panel '+system.upper(),['system-'+system])
for system,wave,pl,onset in [('i',625,820,600),('ii',700,950,700),('iii',670,820,650)]:
 item('properties','absorption-'+system,'System '+system.upper()+': lowest allowed optical transition',f'The minimum of the second derivative of absorption is reported at {wave} nm for system {system.upper()}, assigned to the lowest optically allowed transition. This is not the same quantity as its emission maximum or the onset of the long-lived transient signal.',2,'Absorption Spectra, transition assignments',['system-'+system])
 item('properties','emission-'+system,'System '+system.upper()+': emission maximum',f'The broad photoluminescence maximum is reported at {pl} nm for system {system.upper()}. The authors attribute the weak emission predominantly to trapping states. Figure 3 uses arbitrary intensity, so the plotted height is not an absolute quantum yield.',3,'Figure 3 and emission discussion',['system-'+system])
 item('properties','dynamics-'+system,'System '+system.upper()+': transient-decay crossover',f'The longer-lived negative transient component first appears near {onset} nm for system {system.upper()}. At higher photon energy the source reports a roughly 5 ps component; at lower energy the fitted decay times increase with increasing wavelength. A single wavelength-independent lifetime is not assigned to the whole particle.',3,'Energy Dependence of the Relaxation Dynamics',['system-'+system])
more('absorption-stages-ii',2,'Absorption Spectra, five-stage series');more('absorption-stages-iii',2,'Absorption Spectra, six-stage series')
rows('properties',[
('absorption-comparison','Absorption shifts and oscillator-strength comparison','Starting from the core spectrum described at 470 nm, the plotted sequences red-shift as well thickness or total particle size increases. System III’s 670 nm transition lies between system I at 625 nm and system II at 700 nm. The source reports approximately twice the lowest-transition oscillator strength for III relative to I and II, while I and II have comparable oscillator strength; an absolute oscillator strength is not tabulated.',3,'Figure 2 caption',['optical-comparison']),
('emission-comparison','Emission onset and trap-state comparison','Emission onsets follow the absorption ordering, with III between I and II, whereas I and III share an 820 nm emission maximum and II peaks at 950 nm. Quantum yield is estimated below 1% for all systems. This study-wide upper estimate is not three separately calibrated quantum-yield determinations.',3,'Emission Spectra',['optical-comparison']),
('figure2-axes','Figure 2: optical density and axes','The original absorption panels use energy from approximately 1.2 to 3.0 eV, with upper wavelength ticks at 1,000, 800 and 600 nm. Vertical axes are absorption in optical density, with different panel ranges. The spectra are kept as original source curves; exact point arrays, baseline procedures and derivative data are not supplied.',3,'Figure 2',['absorption-acquisition'],'method_context'),
('figure3-axes','Figure 3: arbitrary-unit luminescence','All three emission panels plot PL intensity in arbitrary units versus energy, approximately 1.2–3.0 eV, with upper wavelength ticks at 1,000, 800 and 600 nm. Noise and source-subtracted baseline excursions are preserved. Curves are neither smoothed nor reconstructed.',3,'Figure 3',['photoluminescence-acquisition'],'method_context'),
('figure4-decays','Figure 4: energy-dependent fitted decay times','The main panels plot fitted negative-transient decay time in ps against energy over approximately 1.2–3.0 eV, with an upper wavelength scale. Straight lines are least-squares fits described mainly as visual aids; their intersections define the 600/700/650 nm comparisons. No exact lifetime table, numerical fitting uncertainties or full kinetic model is given.',4,'Figure 4 caption',['transient-absorption-acquisition']),
('figure4-insets','Figure 4: selected kinetic traces','Inset traces are labeled 650 and 500 nm for I, 900 and 500 nm for II, and 750 and 600 nm for III. Their axes are delay time in ps, approximately 0–100 ps, and bleach intensity in arbitrary units. The source labels the long-wavelength traces as bleach even though the main discussion interprets their long-lived component as stimulated emission; both are preserved.',4,'Figure 4 insets',['transient-absorption-acquisition']),
])

rows('intuition',[
('motivation','Why a colloidal quantum-dot quantum well?','The introduction contrasts chemically prepared nanoscale wells with physically fabricated multilayer devices requiring expensive clean-room and ultrahigh-vacuum processing. Wet-chemical manipulation and solution deposition motivate an alternative. This is the authors’ rationale, not a demonstrated device fabrication or cost analysis.',1,'Introduction',['literature-context'],'cited_context'),
('well-count-design','Separate well thickness from well count','System II increases the thickness of one HgS well; system III places an additional HgS well across a CdS barrier. Comparing these with system I probes how spatial separation changes carrier confinement and optical transitions. The actual paper tests one stated barrier thickness, rather than a systematic barrier-thickness series.',1,'Abstract and Introduction',['chemical-interpretation'],'model_context','author_interpretation'),
('nucleation-ph','pH-mediated nucleation and growth','The authors propose that high initial pH rapidly ionizes H₂S, enabling many small CdS nuclei. Continued dissociation and precipitation release acidity, slow further growth and lead to the final acidic pH. The printed sulfur-ion notation is S⁻; it is retained as source wording rather than treated as a validated solution-speciation measurement.',1,'Step A chemical explanation',['chemical-interpretation'],'model_context','author_interpretation'),
('exchange-driving-force','Why Hg²⁺ replaces the surface cadmium','The source states that the HgS solubility product is 26 orders of magnitude smaller than that of CdS, motivating surface exchange. This comparative statement is not a measured Ksp determination in the present colloid. It explains the intended conversion of one accessible CdS monolayer to HgS.',2,'Step B chemical explanation',['chemical-interpretation'],'model_context','author_interpretation'),
('cadmium-recycling','Reuse displaced Cd²⁺ during recapping','Hg²⁺ exchange releases Cd²⁺ into the aqueous phase. The source reasons that the displaced amount can form one replacement CdS monolayer when sulfur is supplied. Repeating C without an immediately preceding B requires extra Cd²⁺; otherwise the written layer sequence would not specify the necessary metal supply.',2,'Step B/C connection',['chemical-interpretation'],'model_context','author_interpretation'),
('barrier-design','Why system III contains two CdS barrier layers','Three CdS layers are grown outside the first HgS well before the second exchange. Converting the outermost one to HgS leaves two CdS layers inside the new well. The final C step then caps the second well. Counting deposition steps alone would incorrectly treat all three grown CdS layers as the final barrier.',2,'System III preparation',['chemical-interpretation'],'model_context','author_interpretation'),
('oscillator-interpretation','Possible mixing of states in the two-well particle','The authors describe III as having roughly twice as many atoms as I, and the same HgS amount as II. They attribute its enhanced oscillator strength and new lowest transition at 670 nm to mixing of states from the two HgS wells. These are source interpretations and comparative statements, not a new atom-count determination or independently fitted coupling energy.',2,'Absorption discussion',['chemical-interpretation'],'model_context','author_interpretation'),
('trap-location','Why the emission is assigned to interface traps','Because I and III share the same HgS monolayer thickness and emission peak while II has a thicker HgS well and a red-shifted peak, the authors argue that the dominant trap state depends on well thickness and lies at the CdS/HgS interface rather than the outer particle surface. Prior TEM and ODMR/ESR studies are cited in support; those measurements are not reproduced here.',3,'Emission discussion and references 3, 15',['chemical-interpretation'],'model_context','author_interpretation'),
('bleach-vs-emission','Interpreting the negative transient signal','A negative pump-induced absorption change can result from bleaching or stimulated emission. The authors assign the long-lived component in the luminescence region to stimulated recombination through an inhomogeneous distribution of trapping states, because bleaching requires an absorbing spectral region. The short component at higher energy is assigned to bleach recovery of the lowest optically allowed excitonic state.',3,'Transient absorption discussion',['chemical-interpretation'],'model_context','author_interpretation'),
('theory-context','Scope of the cited calculations','Jaskólski and Bryant’s calculations in reference 18 are described as consistent with prior hole-burning, line-narrowing and transient-absorption observations for I and II. Although Figure 1 sketches wavefunctions for all three architectures, the paper explicitly says no lowest-exciton-energy calculation is available for the present system III. The cited Chang–Xia two-layer theoretical context is also not a computed structure generated in this task.',4,'Discussion preceding Conclusion',['literature-context'],'cited_context'),
('coupling-outlook','Interaction across the CdS barrier','Adding a second adjacent HgS layer gives a larger red shift than adding a second separated well, but the shift for system III still indicates that the wells are not electronically independent. The authors propose varying CdS barrier and HgS well thickness to determine the strength and nature of carrier interactions. Those parameter sweeps are future work, not measured recipes in this article.',4,'Conclusion',['chemical-interpretation'],'author_outlook','author_outlook'),
])
more('bleach-vs-emission',4,'Transient interpretation continuation');more('theory-context',1,'Introduction, reference 19')

rows('sources',[
('identity','Source identity','Markus Braun, Clemens Burda and Mostafa A. El-Sayed, Variation of the Thickness and Number of Wells in the CdS/HgS/CdS Quantum Dot Quantum Well System, Journal of Physical Chemistry A 2001, 105(23), 5548–5551, DOI 10.1021/jp010002l. Received January 3, 2001; final form May 1, 2001; published online May 22, 2001.',1,'Title, author byline, dates and footer',[],'source_metadata','source_metadata'),
('coverage','Supplied main-article coverage','All four supplied main pages have been read and visually inspected, including four figures, preparation methods, captions and all 19 references. Current and legacy PDFs have identical SHA-256 values and represent one source. No supporting-information declaration was found in the supplied pages and no local SI is matched; this does not prove no SI exists.',4,'Complete supplied main article',[],'source_metadata','reviewed_source_limitation'),
('source-context','Affiliation and administrative provenance','The authors are affiliated with Georgia Institute of Technology’s School of Chemistry and Biochemistry. The paper belongs to the Edward W. Schlag Festschrift and identifies El-Sayed as corresponding author. The July 1, 2026 download watermark and PDF metadata are not publication or experiment dates.',1,'Affiliation, footnotes and watermark',[],'source_metadata','source_metadata'),
('core-size-conflict','Core-size discrepancy','The step-A continuation states CdS crystallites grow to 3.5 nm, while the subsequent common system description and Figure 1 use 3.2 nm CdS cores. Neither is silently corrected or averaged. The source does not resolve whether this reflects a preparation variation, measurement difference or typographical error.',2,'Step A continuation, Figure 1 and system dimensions',ROUTES,'curator_interpretation','source_evidence_conflict'),
('inset-label-conflict','Bleach labels versus stimulated-emission interpretation','Figure 4 labels all inset traces as bleach intensity, including the long-wavelength traces at 650, 900 and 750 nm. The caption and discussion assign the low-energy long-lived signal to stimulated emission. The original labeling and the authors’ later interpretation are distinct source assertions.',4,'Figure 4 and transient discussion',['chemical-interpretation'],'curator_interpretation','source_evidence_conflict'),
('temperature-scope','Room temperature belongs to the measurement statement','The room-temperature sentence follows the optical experimental methods. It is retained for absorption, PL and transient-absorption measurements, not automatically imposed as the numerical temperature of core nucleation or cation exchange. No unreported heating, bath, pressure or thermal program is added.',1,'Experimental Section before Sample Preparation',ROUTES,'curator_interpretation','curation_scope'),
('missing-fields','Unreported preparation and structural fields','The Cd/Hg salts and counterions, stabilizer quantity, aqueous H₂S feed concentration/volume, conditional Cd²⁺ charge, pH-adjustment chemicals, stirring speed, exchange dwell, growth duration, synthesis temperature, pressure, purification, isolated yield and storage conditions are not fully specified. Current diffraction, microscopy, elemental maps, atomic coordinates and raw spectral/lifetime arrays are absent. A Raman-subtraction correction is not a published material Raman spectrum.',1,'Preparation and experimental methods',[],'curator_interpretation','reviewed_source_limitation'),
('batch-scope','System labels and experimental lineage','I, II and III designate source architectures and optical comparisons. Figure 2 repeats the first three spectra across panels, but the paper does not identify unique physical batch numbers or independently repeated preparations. Analytical procedures and cited theory are not counted as extra synthesis routes.',3,'Figure 2 and captions',ROUTES,'curator_interpretation','curation_scope'),
('historical-claim','Historical claim and scope','The article presents its two-well colloidal particle as the first chemically prepared multilayer quantum-well structure in a semiconductor quantum dot. This is an attributed 2001 claim, not an independently established current novelty assessment. No device efficiency, application demonstration or present-day literature priority search is supplied here.',1,'Abstract and Introduction',['literature-context'],'cited_context','attributed_historical_claim'),
('acknowledgment','Research support','The Office of Naval Research supported the work under contract N00014-95-1-0306. Markus Braun also acknowledges an Alexander von Humboldt Foundation Feodor Lynen Fellowship. These acknowledgments are administrative provenance rather than experimental conditions.',4,'Acknowledgment',[],'source_metadata','source_metadata'),
])

